{
  "conversations": [
    {
      "title": "Describe my symptoms",
      "lines": [
        {
          "speaker": "you",
          "text": "I have stomach pain."
        },
        {
          "speaker": "partner",
          "text": "How long have you had it?"
        },
        {
          "speaker": "you",
          "text": "Since this morning."
        },
        {
          "speaker": "you",
          "text": "Since yesterday.",
          "or": true
        },
        {
          "speaker": "partner",
          "text": "Do you have diarrhea?"
        },
        {
          "speaker": "you",
          "text": "Yes, I do."
        },
        {
          "speaker": "you",
          "text": "No, just stomach pain.",
          "or": true
        },
        {
          "speaker": "partner",
          "text": "I can help you find medicine."
        }
      ],
      "vocab": [
        "stomach",
        "pain",
        "diarrhea",
        "have",
        "yesterday"
      ]
    },
    {
      "title": "Ask about medication",
      "lines": [
        {
          "speaker": "you",
          "text": "Do you have medicine for stomach pain?"
        },
        {
          "speaker": "partner",
          "text": "Yes, try these tablets."
        },
        {
          "speaker": "you",
          "text": "How many should I take?"
        },
        {
          "speaker": "partner",
          "text": "Take one tablet twice a day."
        },
        {
          "speaker": "you",
          "text": "Should I take it with food?"
        },
        {
          "speaker": "partner",
          "text": "Yes, take it after meals."
        },
        {
          "speaker": "you",
          "text": "How much does it cost?"
        },
        {
          "speaker": "partner",
          "text": "It's ten dollars."
        },
        {
          "speaker": "you",
          "text": "I'll take it."
        },
        {
          "speaker": "you",
          "text": "Thanks."
        }
      ],
      "vocab": [
        "medicine",
        "tablet",
        "take",
        "meal",
        "twice"
      ]
    },
    {
      "title": "Explain allergies",
      "lines": [
        {
          "speaker": "you",
          "text": "I have a drug allergy."
        },
        {
          "speaker": "partner",
          "text": "What are you allergic to?"
        },
        {
          "speaker": "you",
          "text": "I'm allergic to penicillin."
        },
        {
          "speaker": "you",
          "text": "I'm allergic to aspirin.",
          "or": true
        },
        {
          "speaker": "partner",
          "text": "I'll check the ingredients."
        },
        {
          "speaker": "you",
          "text": "Does this medicine contain penicillin?"
        },
        {
          "speaker": "partner",
          "text": "No, it doesn't."
        },
        {
          "speaker": "you",
          "text": "Thanks."
        }
      ],
      "vocab": [
        "allergy",
        "allergic",
        "penicillin",
        "aspirin",
        "ingredient",
        "contain"
      ]
    }
  ]
}
